import math
from collections import defaultdict, Counter

def coprime(a, b):
    return math.gcd(a, b) == 1

def get_divisors(n):
    divs = []
    for i in range(2, int(math.isqrt(n)) + 1):
        if n % i == 0:
            divs.append(i)
            if i != n // i:
                divs.append(n // i)
    if 1 not in divs:
        pass  # divisors > 1 only
    divs.append(n) if n > 1 else None  # ensure n is included
    return sorted([x for x in divs if x > 1])

def prime_factors(x):
    pf = Counter()
    d = 2
    temp = x
    while d * d <= temp:
        while temp % d == 0:
            pf[d] += 1
            temp //= d
        d += 1
    if temp > 1:
        pf[temp] += 1
    return pf

def can_arrange_zero_moves(n):
    divs = get_divisors(n)
    m = len(divs)
    if m <= 2:
        return 0, divs

    graph = defaultdict(set)
    adj = defaultdict(list)

    for i in range(len(divs)):
        for j in range(i+1, len(divs)):
            a, b = divs[i], divs[j]
            if not coprime(a, b):
                graph[divs[i]].add(divs[j])
                graph[divs[j]].add(divs[i])
                adj[divs[i]].append(divs[j])
                adj[divs[j]].append(divs[i])

    def dfs_start(node, order, visited):
        visited[node] = True
        order.append(node)
        for neighbor in adj[node]:
            if neighbor not in visited:
                dfs_start(neighbor, order, visited)

    start = divs[0]
    visited = {divs[i]: False for i in range(len(divs))}
    order = []
    dfs_start(start, order, visited)

    if len(order) == len(divs):
        return 0, order

    # Find good adjacent pairs to place non-coprime
    order = divs + divs  # Extend for circular

