import sys

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    arr = list(map(int, lines[1].split()))

    MOD = 1000000007

    placed_values = set()
    empty_positions = []

    for i, val in enumerate(arr):
        idx = i + 1
        if val != -1:
            placed_values.add(val)
        else:
            empty_positions.append(idx)

    m = len(empty_positions)
    available_values = set(range(1, n + 1)) - placed_values

    dangerous_count = 0
    for pos in empty_positions:
        if pos in available_values:
            dangerous_count += 1

    k = m

    fact = [1] * (k + 1)
    for i in range(2, k + 1):
        fact[i] = (fact[i-1] * i) % MOD

    def mod_inverse(a):
        return pow(a, MOD - 2, MOD)

    def nCr_mod(n, r):
        if r < 0 or r > n:
            return 0
        if r == 0:
            return 1
        numerator = 1
        denominator = 1
        for i in range(r):
            numerator = numerator * (n - i) % MOD
            denominator = denominator * (i + 1) % MOD
        return numerator * mod_inverse(denominator) % MOD

    result = 0
    for j in range(dangerous_count + 1):
        combinations = nCr_mod(dangerous_count, j)
        arrangements = fact[k - j]
        term = combinations * arrangements % MOD

        if j % 2 == 0:
            result = (result + term) % MOD
        else:
            result = (result - term + MOD) % MOD

    return str(result) + '\n'

