def solution(input_str):
    input_str = input_str.strip()
    if not input_str:
        return "0"

    parts = input_str.split()
    if len(parts) >= 2:
        n = int(parts[0])
        m = int(parts[1])
    else:
        return "0"

    total_cells = n * m

    # Precompute reach_from[i]: bitmask of cells that can reach cell i
    reach_from = [0] * total_cells
    for i in range(total_cells):
        r, c = divmod(i, m)
        mask = 0
        for dr, dc in [(0, 0), (0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m:
                mask |= (1 << (nr * m + nc))
        reach_from[i] = mask

    # Greedy algorithm to find minimum dominating set
    current_cover = 0
    selected_size = 0

    while current_cover != (1 << total_cells) - 1:
        best_idx = -1
        best_gain = 0

        for i in range(total_cells):
            for existing in range(selected_size + 1):
                if (current_cover & reach_from[i] & (1 << existing)) != 0:
                    continue
            gain = reach_from[i] & ~current_cover
            if gain > best_gain:
                best_gain = gain
                best_idx = i

        if best_idx < 0:
            break

        current_cover |= reach_from[best_idx]
        selected_size += 1

    return f"{total_cells - selected_size}"

