def is_prime(num):
    if num < 2:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    if num == 3:
        return True
    if num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def get_prime_factors(n):
    factors = set()
    d = 2
    temp = n
    if temp == 1:
        return factors
    while d * d <= temp:
        while temp % d == 0:
            factors.add(d)
            temp //= d
        d += 1
    if temp > 1:
        factors.add(temp)
    return factors

def pow_mod(base, exp, mod):
    """Computes base^exp % mod efficiently"""
    result = 1
    base = base % mod
    if mod == 1:
        return 0
    while exp > 0:
        if exp & 1:
            result = (result * base) % mod
        exp >>= 1
        base = (base * base) % mod
    return result

def gcd(a, b):
    """Computes GCD using Euclidean algorithm"""
    while b:
        a, b = b, a % b
    return a

