def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    s = lines[1]
    t = lines[2]

    if m > n:
        return "0\n"

    result = []

    for i in range(n - m + 1):
        valid = True
        trans_map = {}

        for j in range(m):
            c_s = s[i + j]
            c_t = t[j]

            if c_s == c_t:
                # Self mapping - character maps to itself
                if trans_map.get(c_s, None) != c_t:
                    valid = False
                    break
            else:
                # Bidirectional mapping required
                if c_s in trans_map:
                    # Already mapped, check consistency
                    if trans_map[c_s] != c_t:
                        valid = False
                        break
                elif c_t in trans_map:
                    # c_s is new but its target c_t is already mapped
                    # Check if c_t's mapping matches c_s
                    if trans_map[c_t] != c_s:
                        valid = False
                        break
                else:
                    # Create bidirectional mapping
                    trans_map[c_s] = c_t
                    trans_map[c_t] = c_s

        if valid and all(v == k for k, v in trans_map.items()):
            # Additional check: verify the mapping is an involution
            # for every k in trans_map, trans_map[k] should have trans_map[trans_map[k]] == k
            involution_ok = True
            keys = list(trans_map.keys())
            for k in keys:
                v = trans_map[k]
                if trans_map[v] != k:
                    involution_ok = False
                    break
            if not involution_ok:
                valid = False

            if valid:
                result.append(i + 1)

    result.sort()
    out = str(len(result)) + "\n"
    out += " ".join(map(str, result)) + "\n"
    return out

