import sys
from collections import deque, defaultdict

def read_input(lines):
    parts = lines[0].split()
    n, m = int(parts[0]), int(parts[1])

    adj = defaultdict(list)
    for i in range(1, m + 1):
        parts = lines[i].split()
        u, v = int(parts[0]), int(parts[1])
        adj[u].append(v)

    return n, m, adj

def bfs_shortest_paths(n, adj):
    dist = [[float('inf')] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        dist[i][i] = 0
        queue = deque([i])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if dist[i][v] == float('inf') and dist[i][u] + 1 < dist[i][v]:
                    dist[i][v] = dist[i][u] + 1
                    queue.append(v)
    return dist

def solution(lines):
    data = read_input(lines)
    n, m, adj = data

    dist = bfs_shortest_paths(n, adj)

    max_total = -1
    best_quad = None

    # Initialize to a valid solution
    # This will be overwritten

    # We can optimize by only checking pairs that are actually reachable
    valid_adj = [[False] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if dist[i][j] != float('inf'):
                valid_adj[i][j] = True

    # Group valid pairs by destination to speed up
    max_to = [0] * (n + 1)  # max distance from somewhere to i
    max_from = [0] * (n + 1)  # max distance from i to somewhere
    max_to_node = [0] * (n + 1)
    max_from_node = [0] * (n + 1)

    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if valid_adj[i][j] and dist[i][j] > 0:
                if dist[i][j] > max_from[i]:
                    max_from[i] = dist[i][j]
                    max_from_node[i] = j

    for j in range(1, n + 1):
        for i in range(1, n + 1):
            if valid_adj[i][j] and dist[i][j] > 0:
                if dist[i][j] > max_to[j]:
                    max_to[j] = dist[i][j]
                    max_to_node[j] = i

    # For each possible middle pair (b, c), find best a and d
    for b in range(1, n + 1):
        for c in range(1, n + 1):
            if b == c or not valid_adj[b][c]:
                continue

            # Find best a for this b (a -> b)
            best_a = -1
            best_a_dist = 0
            for a in range(1, n + 1):
                if a != b and valid_adj[a][b] and dist[a][b] > best_a_dist:
                    best_a_dist = dist[a][b]
                    best_a = a

            if best_a == -1:
                continue

            # Find best d for this c (c -> d)
            best_d = -1
            best_d_dist = 0
            for d in range(1, n + 1):
                if d != c and valid_adj[c][d] and dist[c][d] > best_d_dist:
                    best_d_dist = dist[c][d]
                    best_d = d

            if best_d == -1:
                continue

            total = best_a_dist + dist[b][c] + best_d_dist

            # Check if we have all 4 distinct
            if total > max_total:
                max_total = total
                best_quad = (best_a, b, c, best_d)

    if best_quad is None:
        # Fallback - just return any valid 4 cities
        return " ".join(map(str, find_valid_4(n, dist)))

    return " ".join(map(str, best_quad))

def find_valid_4(n, dist):
    # Simple fallback to find any 4 cities
    cities = list(range(1, n + 1))
    # Try to find 4 cities in a chain
    for _ in range(n):
        for i in range(len(cities)):
            for j in range(len(cities)):
                for k in range(len(cities)):
                    l = cities[i]
                    visited = {l}
                    if cities[j] not in visited:
                        l2 = cities[j]
                        visited.add(l2)
                        for m_idx in range(len(cities)):
                            if cities[m_idx] not in visited:
                                visited.add(cities[m_idx])
                                m_idx += 1
                                if len(visited) >= 4:
                                    return list(visited)[:4]
    return [1, 2, 3, 4]

