def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    grid = lines[1:n+1]

    # Parse grid: store fixed colors or None
    parsed = []
    for i in range(n):
        row = []
        for c in grid[i]:
            if c != '0':
                row.append(int(c))
            else:
                row.append(None)
        parsed.append(row)

    # Recursive backtracking with early validation
    result = [[None] * m for _ in range(n)]

    def get_neighbors(r, c):
        neighbors = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    neighbors.append((nr, nc))
        return neighbors

    def is_valid(r, c, color):
        """Check if placing color at (r,c) causes conflict"""
        if parsed[r][c] is not None:
            return parsed[r][c] == color

        # Check neighbors
        for nr, nc in get_neighbors(r, c):
            if result[nr][nc] == color:
                return False
        return True

    def backtrack(idx):
        if idx == n * m:
            return True

        r, c = idx // m, idx % m

        # If preassigned, verify and set
        if parsed[r][c] is not None:
            if not is_valid(r, c, parsed[r][c]):
                return False
            result[r][c] = parsed[r][c]
            return backtrack(idx + 1)

        # Try each color
        for color in [1, 2, 3, 4]:
            if is_valid(r, c, color):
                result[r][c] = color
                if backtrack(idx + 1):
                    return True
                result[r][c] = None

        return False

    if backtrack(0):
        output = []
        for r in range(n):
            row = ''.join(str(result[r][c]) for c in range(m))
            output.append(row)
        return '\n'.join(output)
    else:
        return "0"


