def solution(matrix_input):
    """
    Solves the problem of finding a path from top-left to bottom-right of an n×n matrix
    such that the product of numbers along the path has the minimum number of trailing zeros.

    Trailing zeros come from factors of 10 = 2 × 5.
    We count factors of 2 and 5 for each number, then find the path that minimizes min(total_2, total_5).
    """
    n_str = matrix_input.split('\n')[0]
    n = int(n_str)

    matrix = []
    current_num = 0
    for i in range(1, n + 1):
        line = matrix_input.split('\n')[i]
        if i == n and line == '':
            break
        parts = list(map(int, line.strip().split()))
        matrix.append(parts)

    def count_twos(num):
        if num == 0:
            return float('inf')
        cnt = 0
        while num > 0 and num % 2 == 0:
            cnt += 1
            num //= 2
        return cnt

    def count_fives(num):
        if num == 0:
            return float('inf')
        cnt = 0
        while num > 0 and num % 5 == 0:
            cnt += 1
            num //= 5
        return cnt

    # dp[i][j] = list of (total_2_2, total_5_2) Pareto optimal states
    dp = [[[] for _ in range(n)] for _ in range(n)]

    # Calculate prime factors for all numbers in matrix
    twos = [[count_twos(matrix[i][j]) for j in range(n)] for i in range(n)]
    fives = [[count_fives(matrix[i][j]) for j in range(n)] for i in range(n)]

    # Process cell by cell (row-major order works for right/down moves)
    for i in range(n):
        for j in range(n):
            if i == 0 and j == 0:
                dp[i][j] = [(twos[0][0], fives[0][0])]
            else:
                candidates = []
                if i > 0:
                    for (t2_prev, t5_prev) in dp[i-1][j]:
                        candidates.append((t2_prev + twos[i][j], t5_prev + fives[i][j]))
                if j > 0:
                    for (t2_prev, t5_prev) in dp[i][j-1]:
                        candidates.append((t2_prev + twos[i][j], t5_prev + fives[i][j]))

                # Remove dominated states (dominated means both t2 and t5 >= another state)
                pareto = []
                for state in candidates:
                    is_dominated = False
                    for other in pareto:
                        if other[0] <= state[0] and other[1] <= state[1]:
                            is_dominated = True
                            break
                    if not is_dominated:
                        pareto.append(state)

                dp[i][j] = sorted(pareto, key=lambda x: x[0] + x[1])

    # Find best result from final cell
    final_states = dp[n-1][n-1]
    if not final_states:
        return "0\n" + "".join(["D"] * n + ["R"] * n)

    best_state = min(final_states, key=lambda x: min(x[0], x[1]))
    min_zeros = min(best_state[0], best_state[1])

    # Reconstruct path
    path = []
    i, j = n - 1, n - 1
    while True:
        t2, t5 = best_state

        if i == 0 and j == 0:
            break

        # Check if we came from top
        if i > 0:
            if (t2 - twos[i][j], t5 - fives[i][j]) in dp[i-1][j] and \
               (dp[i-1][j][0][0] == t2 - twos[i][j] if dp[i-1][j] else False):
                path.append('D')
                best_state = (t2 - twos[i][j], t5 - fives[i][j])
                i -= 1
                continue

        # Otherwise came from left
        if j > 0:
            path.append('R')
            best_state = (t2 - twos[i][j], t5 - fives[i][j])
            j -= 1
            continue

    path.reverse()
    return f"{min_zeros}\n{''.join(path)}"

