def solution(input_str):
    MOD = 1000000007
    try:
        a, b, k, t = map(int, input_str.strip().split())
    except ValueError:
        return '0'

    # After t turns, each player's total change is the sum of t values in [-k, k]
    # Memory wins when: a + sum(mem) > b + sum(lexa)
    # Equivalent to: sum(mem) - sum(lexa) > b - a

    # diff_ways[d] = number of ways to get difference d in ONE turn
    # where d = mem - lexa, and d ranges from -2k to 2k
    diff_ways = [0] * (4 * k + 1)
    for x in range(-k, k + 1):
        for y in range(-k, k + 1):
            diff_ways[x - y + 2 * k] += 1

    if t == 0:
        return '1' if a > b else '0'

    # Use polynomial exponentiation to compute distribution after t turns
    # P(z)^t gives the distribution after t turns

    def poly_mul_mod(A, B, mod):
        C = [0] * (len(A) + len(B) - 1)
        for i in range(len(A)):
            a_i = A[i]
            if a_i == 0:
                continue
            for j in range(len(B)):
                C[i + j] = (C[i + j] + a_i * B[j]) % mod
        return C

    def poly_pow_mod(P, power, mod):
        result = [1]  # Identity element
        base = P[:]
        while power > 0:
            if power & 1:
                result = poly_mul_mod(result, base, mod)
            base = poly_mul_mod(base, base, mod)
            power >>= 1
        return result

    # Compute diff_ways^t
    P_final = poly_pow_mod(diff_ways, t, MOD)

    # Calculate answer: sum of ways where final difference > b - a
    target = b - a
    offset = 2 * k * t

    ans = 0
    for i in range(len(P_final)):
        d = i - offset
        if d > target:
            ans = (ans + P_final[i]) % MOD

    return str(ans)

