def eval_game(s, e):
    @lru_cache(maxsize=None)
    def solve(a):
        moves = [2*a, a+1]
        winning_moves = [m for m in moves if m <= e]

        if not winning_moves:
            return False

        for m in winning_moves:
            if not solve(m):
                return True

        return False

    return solve(s)

