            # Check if it's ++a or a++
            if i + 2 < n and expression[i] == 'a' and expression[i+1:i+3] == '++':
                op = 'a++'
                i += 3
            elif i + 2 < n and expression[i:i+2] == '++':
                op = '++a'
                i += 2
            else:
                op = 'a++'
                i += 1
        else:
            op = 'a++'
            i += 1

        # Calculate coefficient with sign
        coef = num * sign

        terms.append((coef, op))

