def solution(input_str):
    n, k = map(int, input_str.split())

    MOD = 10**9 + 7

    # Precompute factorials and inverse factorials
    fact = [1] * n
    inv = [1] * n

    for i in range(1, n):
        fact[i] = fact[i-1] * i % MOD

    inv[n-1] = pow(fact[n-1], MOD-2, MOD)
    for i in range(n-2, -1, -1):
        inv[i] = inv[i+1] * (i+1) % MOD

    def C(n, r):
        if r < 0 or r > n:
            return 0
        return fact[n] * inv[r] % MOD * inv[n-r] % MOD

    total_good = 0
    for i in range(n):
        valid_j = min(i, k)
        total_good = (total_good + valid_j * C(n-1, i) * fact[i-1] if i > 0 else 0) * fact[n-1-i] % MOD

    total_perms = fact[n]
    answer = (total_perms - total_good + MOD) % MOD
    return str(answer)

