def solution(input_str):
    data = input_str.strip().split('\n')
    n, m = map(int, data[0].split())

    frogs = []
    for i in range(n):
        p, a = map(int, data[1 + i].split())
        frogs.append({
            'id': i + 1,
            'pos': p,
            'ai': a,
            'active': True
        })

    turn = 0
    while True:
        # Find the next active frog in turn order
        while turn < n and not frogs[turn]['active']:
            turn += 1

        if turn >= n:
            break

        # Get current frog
        frog = frogs[turn]

        # Calculate landing position (cyclic)
        new_pos = ((frog['pos'] - 1 + frog['ai']) % m) + 1

        # Count and remove frogs on the path
        knocked = 0
        for other in frogs:
            if not other['active'] or frog['id'] == other['id']:
                continue

            # Check if other is on the cyclic path from frog['pos'] to new_pos
            start = frog['pos']
            end = new_pos

            if start <= end:
                # Path doesn't wrap around
                if start <= other['pos'] <= end:
                    knocked += 1
                    other['active'] = False
            else:
                # Path wraps around
                if other['pos'] >= start or other['pos'] <= end:
                    knocked += 1
                    other['active'] = False

        frog['ai'] -= knocked
        frog['pos'] = new_pos

        if frog['ai'] <= 0:
            frog['active'] = False

        # Move to next frog (handle wrapping)
        turn = (turn + 1) % n

    remaining = [f['id'] for f in frogs if f['active']]
    return "{}\n{} ".format(len(remaining), ' '.join(map(str, remaining)))
